    /// Generates a random packet with the given id (test support).
    #[cfg(feature = "testgen")]
    pub fn generate_by_id(id: i32, g: &mut Gen) -> Option<Self> {
        match id {
            id::KEEP_ALIVE => Some(Self::KeepAlive(<KeepAlive as Generate>::generate(g))),
            id::CHAT => Some(Self::Chat(<Chat as Generate>::generate(g))),
            id::USE_ENTITY => Some(Self::UseEntity(<UseEntity as Generate>::generate(g))),
            id::FLYING => Some(Self::Flying(<Flying as Generate>::generate(g))),
            id::POSITION => Some(Self::Position(<Position as Generate>::generate(g))),
            id::LOOK => Some(Self::Look(<Look as Generate>::generate(g))),
            id::POSITION_LOOK => Some(Self::PositionLook(<PositionLook as Generate>::generate(g))),
            id::BLOCK_DIG => Some(Self::BlockDig(<BlockDig as Generate>::generate(g))),
            id::BLOCK_PLACE => Some(Self::BlockPlace(<BlockPlace as Generate>::generate(g))),
            id::HELD_ITEM_SLOT => Some(Self::HeldItemSlot(<HeldItemSlot as Generate>::generate(g))),
            id::ARM_ANIMATION => Some(Self::ArmAnimation(<ArmAnimation as Generate>::generate(g))),
            id::ENTITY_ACTION => Some(Self::EntityAction(<EntityAction as Generate>::generate(g))),
            id::STEER_VEHICLE => Some(Self::SteerVehicle(<SteerVehicle as Generate>::generate(g))),
            id::CLOSE_WINDOW => Some(Self::CloseWindow(<CloseWindow as Generate>::generate(g))),
            id::WINDOW_CLICK => Some(Self::WindowClick(<WindowClick as Generate>::generate(g))),
            id::TRANSACTION => Some(Self::Transaction(<Transaction as Generate>::generate(g))),
            id::SET_CREATIVE_SLOT => Some(Self::SetCreativeSlot(
                <SetCreativeSlot as Generate>::generate(g),
            )),
            id::ENCHANT_ITEM => Some(Self::EnchantItem(<EnchantItem as Generate>::generate(g))),
            id::UPDATE_SIGN => Some(Self::UpdateSign(<UpdateSign as Generate>::generate(g))),
            id::ABILITIES => Some(Self::Abilities(<Abilities as Generate>::generate(g))),
            id::TAB_COMPLETE => Some(Self::TabComplete(<TabComplete as Generate>::generate(g))),
            id::SETTINGS => Some(Self::Settings(<Settings as Generate>::generate(g))),
            id::CLIENT_COMMAND => Some(Self::ClientCommand(<ClientCommand as Generate>::generate(
                g,
            ))),
            id::CUSTOM_PAYLOAD => Some(Self::CustomPayload(<CustomPayload as Generate>::generate(
                g,
            ))),
            id::SPECTATE => Some(Self::Spectate(<Spectate as Generate>::generate(g))),
            id::RESOURCE_PACK_RECEIVE => Some(Self::ResourcePackReceive(
                <ResourcePackReceive as Generate>::generate(g),
            )),
            _ => None,
        }
    }
